\begin{equation*}
\Delta\rho g e_{s}
   =S_{0}\,\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},\qquad 
U\equiv kh ,
\end{equation*}
i.e. in the conventional form $e_{s}=\chi(U)S_{0}/\Delta\rho g$

\begin{equation*}
e_{s}= \chi_{A}(U)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi_{A}(U)=\frac{U\cosh U}{U^{2}+\cosh^{2}U}
          =\Big[\,\frac{U}{\cosh U}+\frac{\cosh U}{U}\Big]^{-1},
\qquad U=kh=\frac{2\pi h}{\lambda},
\end{equation*}
with $\chi_{A}>0$ for $S_{0}>0$ up to the obvious sign convention.
In particular

\begin{equation*}
\chi_{A}(U)=U+O(U^{3}),\qquad U\to0,
\end{equation*}
and

\begin{equation*}
\chi_{A}(U)\sim2U e^{-2U}\to0,\qquad U\to\infty .
\end{equation*}
Hence on the geophysically relevant long-wave thin-plate limit
$U=kh\ll1$,

\begin{equation*}
\cosh U=1+O(U^{2}),\qquad 
\chi_{A}(U)=U+O(U^{3}),
\end{equation*}
so that to leading order

\begin{equation*}
e_{s}\simeq U\,\frac{S_{0}}{\Delta\rho g}
       =kh\,\frac{S_{0}}{\Delta\rho g}
       =\frac{2\pi h}{\lambda}\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
i.e.

\begin{equation*}
\chi_{LW}\simeq kh=\frac{2\pi h}{\lambda} ,
\end{equation*}
the usual viscous dynamic-topography scaling
$e_{s}\propto S_{0}/\Delta\rho g$ with the shape factor $kh$.
The viscosity drops out of the steady balance.  With the often used
impermeable base normalisation $w(h)=0$, $\Phi(h)=0$, the familiar
lubrication form

\begin{equation*}
\chi_{L}(U)=\frac{U}{\cosh U+U\sinh U}
          =\frac{1}{\sinh U+U^{-1}\cosh U},
\end{equation*}
is obtained, $\chi_{L}=U+O(U^{3})$ for $U\ll1$ and
$\chi_{L}\sim U\,{\rm sech}\,U$ for $U\gg1$.  $\chi_{L}$ coincides with
$\chi_{A}$ to $O(U)$, $\chi_{L}= \chi_{A}+O(U^{3})$, and gives the
same thin-plate long-wave limit $\chi\simeq kh$, 
$e_{s}\approx kh\,S_{0}/\Delta\rho g$, normally quoted as
$e_{s}\approx (2\pi h/\lambda)S_{0}/\Delta\rho g$.  The sign is
reversed with the conventional geophysical sign convention
$\sigma_{xz}(h)=-S_{0}$.

Up to the $\rho\leftrightarrow\Delta\rho$ identification this is the
customary $e_{s}= \chi S_{0}/\Delta\rho g$ steady viscous transfer
function.  In the thin-plate limit the often quoted form is simply
$\chi\simeq kh$ and $e_{s}\simeq kh\,S_{0}/\Delta\rho g$.  The exact
Stokes transfer function with free vertical motion at the base is the
$U\cosh U/(U^{2}+\cosh^{2}U)$ form above. ∎

7.text:
In the steady state $\dot e=0$ put

\begin{equation*}
\psi (x,z)=\Phi(z)\sin kx,\qquad 
u_{x}=\Phi'\sin kx,\qquad u_{z}=-k\Phi\cos kx,\qquad 
p=P(z)\cos kx ,
\end{equation*}
so that $\nabla^{4}\psi=0$,

\begin{equation*}
\Phi^{iv}-2k^{2}\Phi''+k^{4}\Phi=0 ,\qquad 
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],
\end{equation*}
\begin{equation*}
\sigma_{zz}= -\big[P+2\mu k\Phi'\big]\cos kx
       =\frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,\qquad 
\sigma_{xz}= \mu\big[\Phi''+k^{2}\Phi\big]\sin kx ,
\end{equation*}
and on the rigid free lid $u_{x}(0)=0$,

\begin{equation*}
\Phi(0)=\Phi'(0)=0,\qquad 
\sigma_{zz}(0)=-P(0)=\frac{\mu}{k}\Phi'''(0)\cos kx .
\end{equation*}
With the buoyant normalisation
$\sigma_{zz}(0)=\Delta\rho g\,e\cos kx$,
\begin{equation*}
\frac{\mu}{k}\Phi'''(0)=\Delta\rho g\,e_{s},\qquad 
\Phi'''(0)=\frac{k\Delta\rho g}{\mu}e_{s},
\end{equation*}
so that the viscosity can be eliminated in the steady balance.
Up to rigid motion

\begin{equation*}
\Phi(z)=c\,z\cosh kz-c\,k^{-1}\sinh kz-
d\,k^{-1}z\sinh kz,
\end{equation*}
so that on the lid
$\sigma_{zz}(0)=2\mu kc\cos kx$ and $\Phi'''(0)=2k^{2}c$.  On the
permeable base
\begin{equation*}
\sigma_{zz}(h)=0\iff \Phi'''(h)=3k^{2}\Phi'(h),\qquad 
\sigma_{xz}(h)=S_{0}\sin kx\iff 
\mu\Big[\Phi''(h)+k^{2}\Phi(h)\Big]=S_{0},
\end{equation*}
i.e. with $U=kh$
\begin{equation*}
\big(c+dh\big)\cosh U=kch\sinh U,\qquad
d=c\Big[k\tanh U-h^{-1}\Big],
\end{equation*}
and
\begin{equation*}
S_{0}=2\mu c\,\frac{U^{2}+\cosh^{2}U}{h\cosh U}\;,
\qquad 
c=\frac{S_{0}h\cosh U}
        {2\mu\big[U^{2}+\cosh^{2}U\big]} .
\end{equation*}
Hence
\begin{equation*}
\Delta\rho g\,e_{s}=2\mu kc
   =S_{0}\,\frac{U\cosh U}{U^{2}+\cosh^{2}U},\qquad 
U=kh=\frac{2\pi h}{\lambda},
\end{equation*}
i.e. on the normalisation $e_{s}=\chi(U)S_{0}/\Delta\rho g$,

\begin{equation*}
\chi_{\rm ex}(U)=\frac{U\cosh U}{U^{2}+\cosh^{2}U}
       =\Big[\frac{U}{\cosh U}+\frac{\cosh U}{U}\Big]^{-1}>0,
\qquad U=kh ,
\end{equation*}
which is $\mu$–independent in the steady state.  In particular

\begin{equation*}
\chi_{\rm ex}(U)=U+O(U^{3}),\qquad U\to0,\qquad
\chi_{\rm ex}(U)\sim2Ue^{-2U},\qquad U\to\infty,
\end{equation*}
and with the conventional impermeable base $W(h)=0$ normalisation the
lubrication form
\begin{equation*}
\chi_{L}(U)=\frac{U}{\cosh U+U\sinh U}
       =\Big[\sinh U+U^{-1}\cosh U\Big]^{-1}
\end{equation*}
coincides with $\chi_{\rm ex}$ to $O(U)$.

For the geophysically relevant long–wave thin plate $U=kh\ll1$,
$\cosh U=1+O(U^{2})$ and

\begin{equation*}
\chi_{LW}(U)=U+O(U^{3}),\qquad 
e_{s}\simeq U\frac{S_{0}}{\Delta\rho g}
       =kh\,\frac{S_{0}}{\Delta\rho g}
       =\frac{2\pi h}{\lambda}\,\frac{S_{0}}{\Delta\rho g} ,
\end{equation*}
i.e. up to the sign convention
$\chi_{LW}\simeq kh=2\pi h/\lambda$.
With the usual geophysical sign $\sigma_{xz}(h)=-S_{0}$ this is written
as $e_{s}\simeq -kh\,S_{0}/\Delta\rho g$.  On the $\rho$ normalisation
used in the statement $\sigma_{zz}(0)=\rho g e\cos kx$ the same transfer
is $e_{s}=(\rho/\Delta\rho)\chi_{\rm ex}S_{0}/\rho g$, viz.
$e_{s}\simeq (\rho/\Delta\rho)kh\,S_{0}/\rho g$ in the long wave limit,
the familiar viscosity–independent viscous dynamic topography
$e_{s}\propto S_{0}/\Delta\rho g$ with the shape factor $kh$.  This is
the $\mu$-free Stokes transfer for the stated
$\sigma_{zz}(h)=0,\;\sigma_{xz}(h)=S_{0}$ free base problem; the sign
is that of $S_{0}$ and is reversed with the conventional geophysical
sign convention. ∎

